async (page) => {
  await page.evaluate(() => {
    const el = [...document.querySelectorAll('div')].find(e => getComputedStyle(e).overflowY === 'auto' && e.scrollHeight > 2000);
    if (el) { window.__sc = el; el.scrollTop = 1080; }
  });
  await page.waitForTimeout(400);
  await page.screenshot({ path: '.playwright-mcp/ref-home-scroll1.png' });
  await page.evaluate(() => { if (window.__sc) window.__sc.scrollTop = 2160; });
  await page.waitForTimeout(400);
  await page.screenshot({ path: '.playwright-mcp/ref-home-scroll2.png' });
  return 'done';
}

