async (page) => {
  const results = [];
  const names = ['Artwork', 'Device screen', 'SVG icon'];
  for (const n of names) {
    await page.goto('http://localhost:36673/');
    await page.getByRole('button', { name: new RegExp(n) }).click();
    await page.waitForTimeout(1500);
    // find large image resource
    const res = await page.evaluate(() => {
      const out = [];
      performance.getEntriesByType('resource').forEach(e => {
        if (/demo-|\.jpg|\.png|\.webp/.test(e.name)) out.push(e.name);
      });
      return { url: location.pathname, res: out };
    });
    results.push({ name: n, ...res });
  }
  return JSON.stringify(results, null, 1);
}

