/* Banner-shaped percent readout: pointed on the side facing the size tag. */
.percent-tag {
  --arrow-width: 14px;
  display: flex;
  align-items: center;
  background: var(--main-theme-color);
  color: #fff;
  position: relative;
  line-height: 1;
