() => {
  const p = document.querySelector('.opts-panel.side-b');
  const st = document.querySelector('.opts-panel.side-b .opts-stack');
  const sc = document.querySelector('.opts-panel.side-b .opts-scroller');
  const r = (e) => e ? {t: Math.round(e.getBoundingClientRect().top), h: Math.round(e.getBoundingClientRect().height), pos: getComputedStyle(e).position, disp: getComputedStyle(e).display, ac: getComputedStyle(e).alignContent, flex: getComputedStyle(e).flex} : null;
  return { panel: r(p), stack: r(st), scroller: r(sc) };
}

