async (page) => {
  const result = {};
  for (const codec of ['webP', 'browserPNG', 'avif', 'oxiPNG']) {
    await page.evaluate((c) => {
      const sel = [...document.querySelectorAll('select')].find(s => [...s.options].some(o=>o.value===c));
      sel.value = c; sel.dispatchEvent(new Event('change', { bubbles: true }));
    }, codec);
    await page.waitForTimeout(2500);
    result[codec] = await page.evaluate(async () => {
      const a = [...document.querySelectorAll('a[download]')].pop();
      const r = await fetch(a.href); const b = await r.blob();
      const buf = new Uint8Array(await b.arrayBuffer());
      return { download: a.download, type: b.type, size: b.size, magic: [...buf.slice(0,12)].map(x=>x.toString(16).padStart(2,'0')).join(' ') };
    });
  }
  return JSON.stringify(result, null, 1);
}

