async () => {
  const c = document.createElement('canvas');
  c.width = 64; c.height = 64;
  const ctx = c.getContext('2d');
  const grad = ctx.createLinearGradient(0,0,64,64);
  grad.addColorStop(0,'#f00'); grad.addColorStop(1,'#00f');
  ctx.fillStyle = grad; ctx.fillRect(0,0,64,64);
  const out = {};
  for (const [name, mime] of [['jpeg','image/jpeg'],['webp','image/webp'],['png','image/png'],['avif','image/avif'],['jxl','image/jxl'],['qoi','image/qoi']]) {
    const b = await new Promise(r => c.toBlob(r, mime, 0.75));
    if (!b) { out[name] = null; continue; }
    const buf = new Uint8Array(await b.arrayBuffer());
    out[name] = { type: b.type, size: b.size, magic: [...buf.slice(0,8)].map(x=>x.toString(16).padStart(2,'0')).join(' ') };
  }
  return out;
}

