async (page) => {
  const dims = () => page.evaluate(async () => {
    const a = [...document.querySelectorAll('a[download]')].pop();
    const r = await fetch(a.href); const b = await r.blob();
    const buf = new Uint8Array(await b.arrayBuffer());
    const bmp = await createImageBitmap(b);
    return { w: bmp.width, h: bmp.height, size: b.size, magic: [...buf.slice(0,4)].map(x=>x.toString(16).padStart(2,'0')).join(' ') };
  });
  const before = await dims();
  await page.getByRole('checkbox', { name: 'Resize' }).check({ force: true });
  await page.waitForTimeout(500);
  const w = page.locator('input[name=width]');
  await w.fill('400');
  await w.blur();
  await page.waitForTimeout(2000);
  const resized = await dims();
  const nums = await page.evaluate(() => [...document.querySelectorAll('input[name]')].map(i=>({n:i.name,v:i.value})));
  // rotate
  await page.getByRole('button', { name: 'Rotate' }).click();
  await page.waitForTimeout(2000);
  const rotated = await dims();
  return { before, resized, rotated, nums };
}

