async (page) => {
  const log = [];
  page.on('pageerror', e => log.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type()==='error') log.push('console: ' + m.text()); });
  // upload via the intro file input
  await page.locator('input[type=file]').first().setInputFiles('/tmp/upload-test.png');
  await page.waitForTimeout(2500);
  const info = await page.evaluate(async () => {
    const reload = (a) => fetch(a.href).then(r=>r.blob()).then(b=>b.arrayBuffer()).then(ab=>{
      const u = new Uint8Array(ab);
      let h = 0; for (let i=0;i<u.length;i++) h = (h*31 + u[i]) >>> 0;
      return { size: u.length, hash: h, magic: [...u.slice(0,8)].map(x=>x.toString(16).padStart(2,'0')).join(' ') };
    });
    const out = [];
    for (const a of document.querySelectorAll('a[download]')) out.push({ download: a.download, ...(await reload(a)) });
    return { url: location.pathname, title: document.title, anchors: out };
  });
  return { log, info };
}

