async (page) => {
  const log = [];
  page.on('pageerror', e => log.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type()==='error') log.push('console: ' + m.text()); });
  await page.getByRole('button', { name: /Device screen/ }).click();
  await page.waitForTimeout(2500);
  const sel = page.locator('select[aria-label="Compress codec"]').nth(1);
  const res = {};
  for (const codec of ['avif','jxl','qoi','oxipng','browser-png','webp2','browser-jpeg','mozjpeg','webp']) {
    await sel.selectOption(codec).catch(e => { res[codec] = 'select-failed'; });
    await page.waitForTimeout(2000);
    res[codec] = await page.evaluate(async () => {
      const a = [...document.querySelectorAll('a[download]')].pop();
      const b = await (await fetch(a.href)).blob();
      const buf = new Uint8Array(await b.arrayBuffer());
      return { name: a.download, type: b.type, size: b.size, magic: [...buf.slice(0,4)].map(x=>x.toString(16).padStart(2,'0')).join(' ') };
    });
  }
  return { log, res };
}

