/* --- two-up --- */
.two-up {
  --split-point: 50%;
  --bar-size: 4px;
  --bar-touch-size: 30px;
  --track-color: var(--pink);
  position: absolute;
  inset: 0;
}
.two-up-handle {
  touch-action: none;
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: var(--bar-touch-size);
  transform: translateX(var(--split-point)) translateX(-50%);
  will-change: transform;
  cursor: ew-resize;
  z-index: 3;
}
.two-up-handle::before {
  content: "";
  display: block;
  height: 100%;
  width: var(--bar-size);
  margin: 0 auto;
  background: var(--track-color);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.5);
}
.two-up-knob {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 40px;
  height: 40px;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

/* --- viewport controls --- */
.viewer-controls {
  display: flex;
  justify-content: center;
  overflow: hidden;
  flex-wrap: wrap;
  grid-area: header;
  align-self: center;
  padding: 9px 66px;
  position: relative;

