77	export type LoadedImage = {
78	  /** Object URL / asset URL of the loaded bitmap. */
79	  url: string;
80	  filename: string;
81	  width: number;
82	  height: number;
83	  /** Source byte size. */
84	  bytes: number;
85	  /** Exact bytes of the opened file, reused for the "Original" export. */
86	  sourceBlob: Blob;
87	  /** True when the file was supplied by the user rather than a demo. */
88	  userProvided: boolean;
89	  codec: string;
90	};
91	
92	export function demoToImage(demo: Demo, sourceBlob: Blob): LoadedImage {
93	  return {
94	    url: demo.source,
95	    filename: demo.filename,
96	    width: demo.width,
97	    height: demo.height,
98	    bytes: sourceBlob.size || bytesForDemo(demo),
99	    sourceBlob,
100	    userProvided: false,
101	    codec: demo.codec,
102	  };
103	}
104	
105	/** Fetches a bundled asset into a Blob so it can be handed back verbatim. */
106	export async function fetchBlob(url: string): Promise<Blob> {
107	  const response = await fetch(url);
108	  return response.blob();
109	}
110	
111	const KB = 1024;
112	const MB = KB * 1024;
113	
114	/** Approximate source sizes, matching the badges on the intro page. */
115	function bytesForDemo(demo: Demo): number {
116	  switch (demo.id) {
117	    case "photo":
118	      return 2.79 * MB;
119	    case "artwork":
120	      return 2.93 * MB;
121	    case "device":
122	      return 1.62 * MB;
123	    default:
124	      return 10.7 * KB;
125	  }
126	}
127	
128	export async function fileToImage(file: File): Promise<LoadedImage> {
129	  const url = URL.createObjectURL(file);
130	  const dims = await measure(url);
131	  return {
132	    url,
133	    filename: file.name,
134	    width: dims.width,
135	    height: dims.height,
136	    bytes: file.size,
137	    // The user's exact bytes — reused untouched for the "Original" export.
138	    sourceBlob: file,
139	    userProvided: true,
140	    codec: pickCodec(file.type),
141	  };
142	}
143	
144	/** SVG needs rasterising before any pixel codec can consume it. */
145	export function isVector(mime: string): boolean {
146	  return mime === "image/svg+xml";
147	}
148	
149	function pickCodec(mime: string): string {
150	  if (mime === "image/png") return "oxipng";
151	  if (mime === "image/svg+xml") return "oxipng";
152	  if (mime === "image/webp") return "webp";
153	  return "mozjpeg";
154	}
155	
156	/** Decodes a blob into the pixels used by the encoder. */
157	export async function decodeBitmap(blob: Blob): Promise<ImageBitmap> {
158	  return createImageBitmap(blob);
159	}
160	
161	function measure(url: string): Promise<{ width: number; height: number }> {
162	  return new Promise((resolve) => {
163	    const img = new Image();
164	    img.onload = () =>
165	      resolve({ width: img.naturalWidth, height: img.naturalHeight });
166	    img.onerror = () => resolve({ width: 0, height: 0 });
167	    img.src = url;
168	  });
169	}

