async (page) => {
  const log = [];
  page.on('pageerror', e => log.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type()==='error') log.push('console: ' + m.text()); });
  const snap = () => page.evaluate(async () => {
    const a = [...document.querySelectorAll('a[download]')].pop();
    const b = await (await fetch(a.href)).blob();
    const buf = new Uint8Array(await b.arrayBuffer());
    let dims = null, decodes = true;
    try { const bmp = await createImageBitmap(b); dims = [bmp.width, bmp.height]; } catch(e) { decodes = false; }
    return { name: a.download, type: b.type, size: b.size, magic: [...buf.slice(0,4)].map(x=>x.toString(16).padStart(2,'0')).join(' '), dims, decodes };
  });
  const base = await snap();
  const sel = page.locator('select[aria-label="Compress codec"]').nth(1);
  await sel.selectOption('webp'); await page.waitForTimeout(2500);
  const webp = await snap();
  await sel.selectOption('mozjpeg'); await page.waitForTimeout(2500);
  await page.getByRole('checkbox', { name: 'Resize' }).check({ force: true });
  await page.waitForTimeout(400);
  const w = page.locator('input[name=width]');
  await w.fill('640'); await w.blur();
  await page.waitForTimeout(2500);
  const resized = await snap();
  await page.getByRole('button', { name: 'Rotate' }).click();
  await page.waitForTimeout(2500);
  const rotated = await snap();
  return { log, base, webp, resized, rotated };
}

