async (page) => {
  const log = [];
  page.on('pageerror', e => log.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type()==='error') log.push('console: ' + m.text()); });
  const steps = [];
  await page.getByRole('button', { name: /Artwork/ }).click();
  await page.waitForTimeout(3000);
  steps.push('opened-artwork:' + (await page.title()));
  // advanced settings
  await page.getByText('Advanced settings').click();
  await page.waitForTimeout(400);
  steps.push('advanced-open');
  // quality slider
  const range = page.locator('.range-track-wrap input[type=range]').first();
  await range.fill('40');
  await page.waitForTimeout(2000);
  steps.push('quality-40');
  // copy over
  await page.getByRole('button', { name: 'Copy settings to other side' }).click();
  await page.waitForTimeout(600);
  steps.push('copied');
  // save + import
  await page.getByRole('button', { name: 'Save side settings' }).click();
  await page.waitForTimeout(400);
  await page.getByRole('button', { name: 'Import saved side settings' }).click();
  await page.waitForTimeout(400);
  steps.push('saved-imported');
  // smoothing + background toggles
  await page.getByRole('button', { name: 'Toggle smoothing' }).click();
  await page.getByRole('button', { name: 'Toggle background' }).click();
  await page.waitForTimeout(400);
  steps.push('toggles');
  // zoom
  await page.getByRole('button', { name: 'Zoom in' }).click();
  await page.getByRole('button', { name: 'Zoom out' }).click();
  steps.push('zoom');
  // download
  const [dl] = await Promise.all([
    page.waitForEvent('download', { timeout: 6000 }).catch(()=>null),
    page.locator('.opts-panel.side-b .dl-btn').click(),
  ]);
