async (page) => {
  const log = [];
  page.on('pageerror', e => log.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type()==='error') log.push('console: ' + m.text()); });
  // Upload a JPEG and verify every listed codec yields decodable bytes with
  // correct extensions, plus resize/rotate dimension changes.
  await page.locator('input[type=file]').first().setInputFiles('/tmp/upload-test.jpg');
  await page.waitForTimeout(2500);
  const snap = () => page.evaluate(async () => {
    const a = [...document.querySelectorAll('a[download]')].pop();
    const b = await (await fetch(a.href)).blob();
    const buf = new Uint8Array(await b.arrayBuffer());
    let dims=null; try { const bm = await createImageBitmap(b); dims=[bm.width,bm.height]; } catch(e){}
    return { name: a.download, type: b.type, magic: [...buf.slice(0,4)].map(x=>x.toString(16).padStart(2,'0')).join(' '), dims };
  });
  const sel = page.locator('select[aria-label="Compress codec"]').nth(1);
  const out = { identity: await snap() };
  for (const c of ['mozjpeg','webp','oxipng','avif','jxl','qoi','browser-jpeg','browser-png','webp2']) {
    await sel.selectOption(c).catch(()=>{});
    await page.waitForTimeout(1600);
    out[c] = await snap();
  }
  return { log, out };
}

