import { useEffect, useMemo, useRef, useState } from "react";
import {
  IDENTITY,
  encodeImage,
  originalResult,
  type EncodeResult,
} from "@/app/encoder";

/** Loads the editor's source bitmap once per URL. */
export function useSourceImage(url: string | undefined) {
  const [img, setImg] = useState<HTMLImageElement | null>(null);

  useEffect(() => {
    if (!url) return;
    let cancelled = false;
    const el = new Image();
    el.decoding = "async";
    el.onload = () => {
      if (!cancelled) setImg(el);
    };
    el.onerror = () => {
      if (!cancelled) setImg(null);
    };
    el.src = url;
    return () => {
      cancelled = true;
      setImg(null);
    };
  }, [url]);

  return img;
}

export type EncodeOptions = {
  codec: string;
  quality: number;
  /** Output size before rotation. */
  width: number;
  height: number;
  resizeEnabled: boolean;
  rotate: number;
};

export type EncodeState = {
  /** Fetchable URL of the produced bytes. */
  url: string;
  bytes: number;
  width: number;
  height: number;
  type: string;
  /** True until the bitmap has decoded and the real codec pass has run. */
  busy: boolean;
};

/**
 * Encodes one side of the editor synchronously from the decoded bitmap.
 *
 * Until the bitmap is ready the result falls back to the untouched source
 * bytes, so the download link is always backed by a real, fetchable file
 * rather than a placeholder.
 */
export function useEncodedImage(
  img: HTMLImageElement | null,
  sourceBlob: Blob | null,
  options: EncodeOptions,
): EncodeState {
  const { codec, quality, width, height, resizeEnabled, rotate } = options;

  const fallback = useMemo<EncodeState | null>(() => {
    if (!sourceBlob) return null;
    const base = originalResult({
      source: document.createElement("canvas"),
      sourceBlob,
      naturalWidth: 0,
      naturalHeight: 0,
      width: 1,
      height: 1,
      rotate: 0,
      codec: IDENTITY,
      quality: 0,
    });
    return { ...base, busy: true };
  }, [sourceBlob]);

  // Release the fallback Blob URL once it is no longer the live result.
  const fallbackUrl = fallback?.url ?? null;
  const usedFallback = useRef<string | null>(null);
  usedFallback.current = fallbackUrl;

  const encoded = useMemo<EncodeState | null>(() => {
    if (!sourceBlob) return null;
    if (!img) return null;
    const naturalWidth = img.naturalWidth || img.width;
    const naturalHeight = img.naturalHeight || img.height;
    if (!naturalWidth || !naturalHeight) return null;
    try {
      const result: EncodeResult = encodeImage({
        source: img,
        sourceBlob,
        naturalWidth,
        naturalHeight,
        codec,
        quality,
        width: resizeEnabled ? width : naturalWidth,
        height: resizeEnabled ? height : naturalHeight,
        rotate,
      });
      return { ...result, busy: false };
    } catch {
      return null;
    }
  }, [
    img,
    sourceBlob,
    codec,
    quality,
    width,
    height,
    resizeEnabled,
    rotate,
  ]);

  // Drop the fallback blob URL when it is superseded.
  const encodedUrl = encoded?.url ?? null;
  useEffect(() => {
    return () => {
      if (fallbackUrl && encodedUrl && fallbackUrl !== encodedUrl) {
        URL.revokeObjectURL(fallbackUrl);
      }
    };
  }, [fallbackUrl, encodedUrl]);

  return (
    encoded ??
    fallback ?? {
      url: "",
      bytes: 0,
      width: 0,
      height: 0,
      type: "",
      busy: true,
    }
  );
}

