async (page) => {
  const log = [];
  page.on('pageerror', e => log.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type()==='error') log.push('console: ' + m.text()); });
  const snap = () => page.evaluate(async () => {
    const out = [];
    for (const a of document.querySelectorAll('a[download]')) {
      let info = { name: a.download, href: a.getAttribute('href')?.slice(0, 24) };
      if (a.href && !a.href.endsWith('#')) {
        try {
          const b = await (await fetch(a.href)).blob();
          const buf = new Uint8Array(await b.arrayBuffer());
          info.type = b.type; info.size = b.size;
          info.magic = [...buf.slice(0,4)].map(x=>x.toString(16).padStart(2,'0')).join(' ');
        } catch(e) { info.err = String(e).slice(0,40); }
      }
      out.push(info);
    }
    return out;
  });
  // check IMMEDIATELY after the demo click resolves
  await page.getByRole('button', { name: /Large photo/ }).click();
  await page.waitForTimeout(300);
  const early = await snap();
  await page.waitForTimeout(2500);
  const late = await snap();
  return { log, early, late };
}

