  page.on('console', m => { if (m.type()==='error') log.push('console: ' + m.text()); });
  const snap = () => page.evaluate(async () => {
    const a = [...document.querySelectorAll('a[download]')].pop();
    const b = await (await fetch(a.href)).blob();
    const buf = new Uint8Array(await b.arrayBuffer());
    let dims=null, decodes=true, hash=0;
    for (let i=0;i<buf.length;i++) hash=(hash*31+buf[i])>>>0;
    try { const bm = await createImageBitmap(b); dims=[bm.width,bm.height]; } catch(e){ decodes=false; }
    return { name:a.download, type:b.type, size:b.size,
      magic:[...buf.slice(0,4)].map(x=>x.toString(16).padStart(2,'0')).join(' '),
      dims, decodes, hash };
  });
  await page.goto('http://localhost:8200/index.html');
  await page.waitForTimeout(400);
  // (1) upload PNG, read the LEFT/original anchor
  await page.locator('input[type=file]').first().setInputFiles('/tmp/upload-test.png');
  await page.waitForTimeout(1600);
  const original = await page.evaluate(async () => {
    const a = [...document.querySelectorAll('a[download]')][0];
    const b = await (await fetch(a.href)).blob();
    const buf = new Uint8Array(await b.arrayBuffer());
    let h=0; for (let i=0;i<buf.length;i++) h=(h*31+buf[i])>>>0;
    return { name:a.download, href:a.getAttribute('href').slice(0,12), size:buf.length, hash:h };
  });
  // (2) JPEG bytes
  await page.getByLabel('Compress codec').last().selectOption('mozjpeg');
  await page.waitForTimeout(1500);
  const jpeg = await snap();
  // (3) WebP bytes
  await page.getByLabel('Compress codec').last().selectOption('webp');
  await page.waitForTimeout(1500);
  const webp = await snap();
  // (4) resize changes dims
  await page.getByRole('checkbox', { name: 'Resize' }).check({ force: true });
  await page.waitForTimeout(300);
  const wi = page.locator('input[name=width]');
  await wi.fill('160'); await wi.blur();
  await page.waitForTimeout(1500);
  const resized = await snap();
  // (5) rotate
  await page.getByRole('button', { name: 'Rotate' }).click();
  await page.waitForTimeout(1500);
  const rotated = await snap();
  return { log, original, jpeg, webp, resized, rotated };
}

