1	/**
2	 * Real image encoding pipeline.
3	 *
4	 * Everything here is synchronous on purpose: the editor must be able to hand
5	 * a browser a ready-to-save file (a fetchable URL plus the exact byte count)
6	 * in the same render that its settings become valid — never a placeholder
7	 * `#` href that would resolve to the document itself.
8	 *
9	 *   - "Original"  → the untouched source bytes, as a Blob URL.
10	 *   - JPEG/WebP/PNG → the browser's own encoders, via canvas `toDataURL`.
11	 *   - QOI → a compact lossless encoder implemented below.
12	 *   - AVIF/JXL (which this browser cannot emit) degrade to real JPEG, and the
13	 *     file name reports the format actually produced.
14	 */
15	
16	export const IDENTITY = "identity";
17	
18	export type EncodeRequest = {
19	  /** Decoded source pixels. */
20	  source: CanvasImageSource;
21	  /** Exact bytes of the file the user opened (used for the "Original" codec). */
22	  sourceBlob: Blob;
23	  /** Source pixel size. */
24	  naturalWidth: number;
25	  naturalHeight: number;
26	  /** Requested output size before rotation. */
27	  width: number;
28	  height: number;
29	  /** Clockwise rotation in degrees (a multiple of 90). */
30	  rotate: number;
31	  codec: string;
32	  /** 0-100 quality for lossy codecs. */
33	  quality: number;
34	};
35	
36	export type EncodeResult = {
37	  /** Fetchable URL (data: or blob:) of the produced bytes. */
38	  url: string;
39	  bytes: number;
40	  width: number;
41	  height: number;
42	  /** MIME type actually produced. */
43	  type: string;
44	};
45	
46	/** Codec keys match the encoder identifiers the reference UI exposes. */
47	const NATIVE_MIME: Record<string, string | null> = {
48	  browserJPEG: "image/jpeg",
49	  mozJPEG: "image/jpeg",
50	  webP: "image/webp",
51	  wp2: "image/webp",
52	  browserPNG: "image/png",
53	  oxiPNG: "image/png",
54	  avif: "image/avif",
55	  jxl: "image/jxl",
56	  qoi: null,
57	};
58	
59	/** Extension used when the browser produced exactly what was asked for. */
60	const EXTENSION: Record<string, string> = {
61	  browserJPEG: "jpg",
62	  mozJPEG: "jpg",
63	  webP: "webp",
64	  wp2: "webp2",
65	  browserPNG: "png",
66	  oxiPNG: "png",
67	  avif: "avif",
68	  jxl: "jxl",
69	  qoi: "qoi",
70	};
71	
72	const EXT_BY_MIME: Record<string, string> = {
73	  "image/jpeg": "jpg",
74	  "image/png": "png",
75	  "image/webp": "webp",
76	  "image/qoi": "qoi",
77	  "image/avif": "avif",
78	  "application/octet-stream": "png",
79	};
80	
81	/**
82	 * Names the saved file after the bytes we actually produced — so a codec the
83	 * browser can't emit (e.g. AVIF) downloads with its real, honest extension.
84	 */
85	export function fileNameFor(
86	  codec: string,
87	  sourceName: string,
88	  producedType: string,
89	): string {
90	  const stem = sourceName.replace(/\.[^.]+$/, "");
91	  if (codec === IDENTITY) {
92	    const match = sourceName.match(/\.([a-z0-9]+)$/i);
93	    return `${stem}.${match ? match[1].toLowerCase() : "png"}`;
94	  }
95	  const native = NATIVE_MIME[codec];
96	  if (native && producedType && producedType !== native) {
97	    return `${stem}.${EXT_BY_MIME[producedType] ?? "jpg"}`;
98	  }
99	  if (producedType && EXT_BY_MIME[producedType]) {
100	    return `${stem}.${EXT_BY_MIME[producedType]}`;
101	  }
102	  return `${stem}.${EXTENSION[codec] ?? "png"}`;
103	}
104	
105	function outDimensions(req: EncodeRequest) {
106	  const quarterTurn = req.rotate % 180 !== 0;
107	  const w = Math.max(1, Math.round(req.width));
108	  const h = Math.max(1, Math.round(req.height));
109	  return quarterTurn ? { w: h, h: w } : { w, h };
110	}
111	
112	/** Draws the source into a fresh canvas, honouring rotation. */
113	function renderCanvas(req: EncodeRequest): HTMLCanvasElement {
114	  const { w, h } = outDimensions(req);
115	  const canvas = document.createElement("canvas");
116	  canvas.width = w;
117	  canvas.height = h;
118	  const ctx = canvas.getContext("2d");
119	  if (!ctx) throw new Error("2D context unavailable");
120	  ctx.save();
121	  ctx.translate(w / 2, h / 2);
122	  ctx.rotate((req.rotate * Math.PI) / 180);
123	  ctx.drawImage(req.source, -req.width / 2, -req.height / 2, req.width, req.height);
124	  ctx.restore();
125	  return canvas;
126	}
127	
128	/** Byte length of the payload inside a `data:` URL, computed in O(1). */
129	function dataUrlBytes(dataUrl: string): number {
130	  const comma = dataUrl.indexOf(",");
131	  if (comma < 0) return 0;
132	  const body = dataUrl.length - comma - 1;
133	  let padding = 0;
134	  if (dataUrl.endsWith("==")) padding = 2;
135	  else if (dataUrl.endsWith("=")) padding = 1;
136	  return Math.floor((body * 3) / 4) - padding;
137	}
138	
139	/** The untouched source file, ready to download. */
140	export function sourceResult(sourceBlob: Blob): EncodeResult {
141	  return {
142	    url: URL.createObjectURL(sourceBlob),
143	    bytes: sourceBlob.size,
144	    width: 0,
145	    height: 0,
146	    type: sourceBlob.type || "application/octet-stream",
147	  };
148	}
149	
150	/** The untouched source at its true (possibly rotated) dimensions. */
151	export function originalResult(req: EncodeRequest): EncodeResult {
152	  const { w, h } = outDimensions(req);
153	  return { ...sourceResult(req.sourceBlob), width: w, height: h };
154	}
155	
156	/**
157	 * Encodes one side of the comparison and returns ready-to-save bytes.
158	 * Never throws for an unknown codec — it degrades to JPEG.
159	 */
160	export function encodeImage(req: EncodeRequest): EncodeResult {
161	  if (req.codec === IDENTITY) return originalResult(req);
162	
163	  const canvas = renderCanvas(req);
164	  const { w, h } = outDimensions(req);
165	
166	  if (req.codec === "qoi") {
167	    const ctx = canvas.getContext("2d");
168	    if (!ctx) throw new Error("2D context unavailable");
169	    const pixels = ctx.getImageData(0, 0, w, h);
170	    const blob = encodeQoi(pixels.data, w, h);
171	    return {
172	      url: URL.createObjectURL(blob),
173	      bytes: blob.size,
174	      width: w,
175	      height: h,
176	      type: "image/qoi",
177	    };
178	  }
179	
180	  const mime = NATIVE_MIME[req.codec] ?? "image/jpeg";
181	  const quality = Math.min(1, Math.max(0.01, req.quality / 100));
182	
183	  let dataUrl = canvas.toDataURL(mime, quality);
184	  // Browsers silently substitute PNG when they can't honour the request.
185	  if (!dataUrl.startsWith(`data:${mime}`)) {
186	    dataUrl = canvas.toDataURL("image/jpeg", quality);
187	  }
188	
189	  const actualMime = dataUrl.slice(5, dataUrl.indexOf(";")) || "image/jpeg";
190	  return {
191	    url: dataUrl,
192	    bytes: dataUrlBytes(dataUrl),
193	    width: w,
194	    height: h,
195	    type: actualMime,
196	  };
197	}
198	
199	/* --------------------------------------------------------------------------
200	 * QOI — "Quite OK Image". A compact lossless format the browser can't write,
201	 * so it is implemented directly here.
202	 * ------------------------------------------------------------------------ */
203	
204	const QOI_OP_RGB = 0xfe;
205	const QOI_OP_RGBA = 0xff;
206	const QOI_OP_INDEX = 0x00;
207	const QOI_OP_DIFF = 0x40;
208	const QOI_OP_LUMA = 0x80;
209	const QOI_OP_RUN = 0xc0;
210	
211	function encodeQoi(
212	  rgba: Uint8ClampedArray,
213	  width: number,
214	  height: number,
215	): Blob {
216	  const headerSize = 14;
217	  const maxSize = width * height * 5 + headerSize + 8;
218	  const out = new Uint8Array(maxSize);
219	  let p = 0;
220	
221	  // magic "qoif", width, height, channels, colorspace
222	  out[p++] = 0x71; // q
223	  out[p++] = 0x6f; // o
224	  out[p++] = 0x69; // i
225	  out[p++] = 0x66; // f
226	  out[p++] = (width >>> 24) & 0xff;
227	  out[p++] = (width >>> 16) & 0xff;
228	  out[p++] = (width >>> 8) & 0xff;
229	  out[p++] = width & 0xff;
230	  out[p++] = (height >>> 24) & 0xff;
231	  out[p++] = (height >>> 16) & 0xff;
232	  out[p++] = (height >>> 8) & 0xff;
233	  out[p++] = height & 0xff;
234	  out[p++] = 4; // channels (RGBA)
235	  out[p++] = 0; // sRGB with linear alpha
236	
237	  const index = new Uint8Array(64 * 4);
238	  let r = 0;
239	  let g = 0;
240	  let b = 0;
