async (page) => {
  const log = [];
  page.on('pageerror', e => log.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type()==='error') log.push('console: ' + m.text()); });
  await page.getByRole('button', { name: /Large photo/ }).click();
  await page.waitForTimeout(2500);
  // Mirror the reference's identifiers exactly.
  const ids = await page.evaluate(() => ({
    codecOptions: [...document.querySelectorAll('select')].map(s => [...s.options].map(o => o.value)),
    names: [...document.querySelectorAll('input,select')].map(e => e.name).filter(Boolean),
  }));
  // select by the reference's values
  const sel = page.locator('select').filter({ hasText: 'MozJPEG' }).first();
  await sel.selectOption('webP');
  await page.waitForTimeout(1500);
  const webp = await page.evaluate(async () => {
    const a = [...document.querySelectorAll('a[download]')].pop();
    const b = await (await fetch(a.href)).blob();
    const u = new Uint8Array(await b.arrayBuffer());
    return { name: a.download, type: b.type, magic: [...u.slice(0,4)].map(x=>x.toString(16).padStart(2,'0')).join(' ') };
  });
  await sel.selectOption('mozJPEG');
  await page.waitForTimeout(1500);
  const jpeg = await page.evaluate(async () => {
    const a = [...document.querySelectorAll('a[download]')].pop();
    const b = await (await fetch(a.href)).blob();
    const u = new Uint8Array(await b.arrayBuffer());
    return { name: a.download, type: b.type, magic: [...u.slice(0,4)].map(x=>x.toString(16).padStart(2,'0')).join(' ') };
  });
  return { log, ids, webp, jpeg };
}

