  const seg = () => page.evaluate(async () => {
    const anchors = [...document.querySelectorAll('a[download]')];
    const a = anchors[anchors.length - 1];
    const b = await (await fetch(a.href)).blob();
    const u = new Uint8Array(await b.arrayBuffer());
    let dims=null; try { const bm = await createImageBitmap(b); dims=[bm.width,bm.height]; } catch(e){}
    return { name: a.download, type: b.type, magic: [...u.slice(0,4)].map(x=>x.toString(16).padStart(2,'0')).join(' '), dims };
