  background: var(--dark-gray);
  color: #fff;
  font: inherit;
  font-size: 1.2rem;
  border: none;
  border-radius: 4px;
  padding: 8px 10px;
}
.field-row select {
  appearance: none;
  -webkit-appearance: none;
  padding-right: 30px;
  cursor: pointer;
}
.field-row .sel-wrap {
  position: relative;
}
.field-row .sel-arrow {
  right: 11px;
}
.field-row .text-field:focus {
  outline: 2px solid var(--main-theme-color);
}

/* --- square blue checkbox --- */
.blue-check {
  display: inline-block;
  position: relative;
  --size: 17px;
  width: var(--size);
  height: var(--size);
}
.blue-check input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: pointer;
  z-index: 1;
}
.blue-check .box {
  display: grid;
  place-items: center;
  width: var(--size);
  height: var(--size);
  box-sizing: border-box;
  border-radius: 3px;
  background: var(--dark-gray);
  border: 1px solid rgba(255, 255, 255, 0.3);
}
.blue-check input:checked + .box {
  background: var(--main-theme-color);
  border-color: var(--main-theme-color);
}
.blue-check .box svg {
  width: 12px;
  height: 12px;
  fill: var(--white);
  opacity: 0;
}
.blue-check input:checked + .box svg {
  opacity: 1;
}
.blue-check input:focus-visible + .box {
  outline: #fff solid 2px;
}

/* --- expander (advanced settings) --- */

