async (page) => {
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type()==='error') errors.push('console: ' + m.text()); });

  const right = () => page.evaluate(async () => {
    const anchors = [...document.querySelectorAll('a[download]')];
    const a = anchors[anchors.length - 1];
    const blob = await (await fetch(a.href)).blob();
    const u = new Uint8Array(await blob.arrayBuffer());
    let dims = null, decodes = true;
    try { const bm = await createImageBitmap(blob); dims = [bm.width, bm.height]; } catch { decodes = false; }
    return { name: a.download, type: blob.type, size: blob.size,
      magic: [...u.slice(0,4)].map(x=>x.toString(16).padStart(2,'0')).join(' '), dims, decodes };
  });
  const left = () => page.evaluate(async () => {
    const a = document.querySelectorAll('a[download]')[0];
    const blob = await (await fetch(a.href)).blob();
    const u = new Uint8Array(await blob.arrayBuffer());
    let h = 0; for (let i=0;i<u.length;i++) h = (h*31 + u[i]) >>> 0;
    return { name: a.download, size: u.length, hash: h, type: blob.type };
  });

  const R = {};
  // A. uploaded pixels survive the original export
  await page.goto('http://localhost:8202/index.html');
  await page.waitForTimeout(400);
  await page.locator('input[type=file]').first().setInputFiles('/tmp/upload-test.png');
  await page.waitForTimeout(1800);
  R.originalExport = await left();
  // B. JPEG bytes
  await page.locator('select').nth(1).selectOption('mozJPEG');
  await page.waitForTimeout(1400);
  R.jpeg = await right();
  // C. WebP bytes
  await page.locator('select').nth(1).selectOption('webP');
  await page.waitForTimeout(1400);
  R.webp = await right();
  // D. resize
  await page.locator('select').nth(1).selectOption('mozJPEG');
  await page.waitForTimeout(1000);
  await page.locator('input[name="resize.enable"]').check({ force: true });
  await page.waitForTimeout(400);
  const w = page.locator('input[name="width"]');
  await w.fill('200');
  await page.waitForTimeout(1500);
  R.resized = await right();
  // E. rotate
  await page.locator('button[title="Rotate"]').click();
  await page.waitForTimeout(1500);
  R.rotated = await right();
  return { errors, R };
}

