async (page) => {
  // Enumerate internal links from the homepage (only the two footer links are external).
  const links = await page.evaluate(() => [...document.querySelectorAll('a')].map(a => a.getAttribute('href')));
  // Layout metrics vs reference
  const mine = await page.evaluate(() => {
    const s = document.querySelector('.intro-view');
    const d = document.querySelector('.demos-band');
    const i = document.querySelector('.info-block');
    const g = (e) => ({ top: Math.round(e.getBoundingClientRect().top + s.scrollTop), h: Math.round(e.getBoundingClientRect().height) });
    return { total: s.scrollHeight, demos: g(d), info: g(i) };
  });
  await page.goto('http://localhost:46211/');
  await page.waitForTimeout(600);
  const ref = await page.evaluate(() => {
    const s = document.querySelector('[class*="_intro_"]');
    const d = document.querySelector('[class*="_demos-container"]');
    const i = document.querySelector('[class*="_info_"]');
    const g = (e) => ({ top: Math.round(e.getBoundingClientRect().top + s.scrollTop), h: Math.round(e.getBoundingClientRect().height) });
    return { total: s.scrollHeight, demos: g(d), info: g(i) };
  });
  return { links, mine, ref };
}

